<?php
require 'includes/functions.php';$u=auth();$prior=(int)q('SELECT COUNT(*) FROM orders WHERE user_id=? AND status<>"cancelled"',[$u['id']])->fetchColumn();require 'includes/header.php';
?><div class="page-heading"><h1><?=e(t('คูปองของฉัน'))?></h1><p><?=e(t('ตรวจสอบเงื่อนไขก่อนใช้ สิทธิ์และส่วนลดจะยืนยันอีกครั้งเมื่อสั่งซื้อ ไม่ต้องกดรับสิทธิ์ล่วงหน้า'))?></p></div><div class="coupon-grid"><?php $couponCount=0;foreach(q('SELECT * FROM promotions WHERE code IS NOT NULL AND active=1 AND starts_at<=NOW() AND ends_at>=NOW() ORDER BY ends_at,id') as $coupon){if(($coupon['audience']==='new'&&$prior>0)||($coupon['audience']==='returning'&&$prior===0))continue;$personal=(int)q('SELECT COUNT(*) FROM promotion_redemptions WHERE promotion_id=? AND user_id=? AND released_at IS NULL',[$coupon['id'],$u['id']])->fetchColumn();$used=(int)q('SELECT COUNT(*) FROM promotion_redemptions WHERE promotion_id=? AND released_at IS NULL',[$coupon['id']])->fetchColumn();if(($coupon['per_user_limit']!==null&&$personal>=$coupon['per_user_limit'])||($coupon['total_limit']!==null&&$used>=$coupon['total_limit']))continue;$couponCount++; ?><article class="coupon-card"><h2><?=e($coupon['name'])?></h2><p class="coupon-code"><?=e($coupon['code'])?></p><p><?=e(['fixed'=>'ส่วนลดจำนวนเงิน','percent'=>'ส่วนลดเปอร์เซ็นต์','shipping'=>'ส่วนลดค่าจัดส่ง','unit_price'=>'ราคาพิเศษ','flash_price'=>'Flash Sale','bundle_price'=>'ซื้อหลายชิ้นราคาพิเศษ'][$coupon['kind']])?>: <?=$coupon['kind']==='percent'?number_format($coupon['value']/100,2).'%':($coupon['kind']==='shipping'&&!(int)$coupon['value']?'ส่งฟรี':money($coupon['value']/100))?></p><p><?=e(t('ยอดซื้อขั้นต่ำ'))?> <?=money($coupon['min_subtotal']/100)?> <?=e(t('· จำนวนขั้นต่ำ'))?> <?=(int)$coupon['min_quantity']?></p><p><?=e(t('ส่วนลดสูงสุด'))?> <?=$coupon['max_discount']?money($coupon['max_discount']/100):'ตามยอดที่ร่วมรายการ'?></p><p><?=e(t('หมดอายุ'))?> <?=e($coupon['ends_at'])?></p><p><?=e(t('ใช้สิทธิ์แล้ว'))?> <?=$personal?> / <?=e($coupon['per_user_limit']??'ไม่จำกัด')?></p><p><?=$coupon['stackable']?'ใช้ร่วมกับโปรโมชั่นที่อนุญาตได้':'ใช้ร่วมกับโปรโมชั่นอื่นไม่ได้'?></p><?php $names=q('SELECT p.name,p.name_en FROM promotion_products pp JOIN products p ON p.id=pp.product_id WHERE pp.promotion_id=?',[$coupon['id']])->fetchAll();$cats=q('SELECT c.name,c.name_en FROM promotion_categories pc JOIN categories c ON c.id=pc.category_id WHERE pc.promotion_id=?',[$coupon['id']])->fetchAll();foreach(array_merge($names,$cats) as $scope): ?><small><?=e(localized_name($scope))?></small><br><?php endforeach ?><a class="button secondary" href="<?=url('checkout.php')?>"><?=e(t('ใช้โค้ดในหน้าชำระเงิน'))?></a></article><?php } if(!$couponCount): ?><p><?=e(t('ยังไม่มีคูปองที่ใช้ได้สำหรับบัญชีนี้'))?></p><?php endif ?></div><?php require 'includes/footer.php'; ?>
